// topology.graph: The graph of a vhost, held to a fixed number of elements
// Generated by `pnpm nx g @app/generators:action topology.graph`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  GraphAnswerSchema,
  MaxElementsSchema,
  VhostNameSchema,
} from './topology-types.ts';

export const TopologyGraphInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  /** Nodes plus edges at most; default and ceiling 2,000. Past it the answer is aggregated. */
  maxElements: MaxElementsSchema.optional(),
  /** Read the broker again instead of using a snapshot taken in the last seconds. */
  refresh: z.boolean().optional(),
});

export const TopologyGraphOutputSchema = GraphAnswerSchema;

export const topologyGraph = defineAction({
  id: 'topology.graph',
  kind: 'query',
  summary: 'The graph of a vhost, held to a fixed number of elements',
  input: TopologyGraphInputSchema,
  output: TopologyGraphOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid, vhost: input.vhost }),
  http: { method: 'POST', path: '/connections/{cid}/topology/graphs' },
  mcp: {
    expose: true,
    mutating: false,
    title: 'Topology graph of a vhost',
    description:
      'Exchanges, queues, bindings, alternate-exchange and dead-letter links of one vhost, at most 2,000 elements; a larger vhost is aggregated and says so.',
  },
  cli: { command: 'topology graph' },
  since: '1.0',
});
